class ReadPath {
  private final Cache cache; private final Store replicas; private final Store primary;
  // single-flight map omitted for brevity: coalesce concurrent misses per key
  Object get(String key, String writerCookie) {
    Object v = cache.get(key);
    if (v != null) return v;
    // read-after-write: route recent writer to primary, others to replica
    Store s = (writerCookie != null && cache.isFreshWriter(writerCookie)) ? primary : replicas;
    Object db = s.read(key); // replica lag tolerated here
    if (db != null) cache.set(key, db, 30); // jitter TTL in real code
    return db;
  }
  void invalidate(String key, long version) {
    // version-gated delete: never resurrect stale data over newer write
    cache.deleteIfVersionLte(key, version);
  }
}
class WritePath {
  private final DurableQueue queue;
  String put(String key, byte[] val, String idemKey) {
    if (!RateLimiter.tryAcquire()) throw new BackpressureException("retry with backoff");
    // idempotency key makes retries safe; queue persists before ack
    return queue.enqueue(new Event(key, val, idemKey, System.nanoTime()));
  }
}
