def read_through(key, cache, replica, primary, must_be_fresh=False):
    v = cache.get(key)
    if v is not None:
        return v
    store = primary if must_be_fresh else replica  # trade-off: freshness vs load
    db = store.read(key)
    if db is not None:
        cache.set(key, db, ttl=30 + random.randint(0, 10))  # jitter defeats stampede
    return db

def buffered_write(key, val, idem_key, queue):
    if not try_acquire():
        raise Backpressure("429 + backoff")  # shed instead of OOM
    queue.enqueue({"key": key, "val": val, "idem": idem_key})  # durable before ack

